import{_ as d,o as e,c as o,a0 as c}from"./chunks/framework.Bmhw_dvp.js";const g=JSON.parse('{"title":"CLI","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://dira.proofer.tech/docs/ref-cli"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"dira"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:url","content":"https://dira.proofer.tech/docs/ref-cli"}],["meta",{"property":"og:title","content":"CLI"}],["meta",{"property":"og:description","content":"티켓을 큐에 넣으면 cron에 물린 워커가 claude 세션에 넘깁니다. 파일시스템이 곧 큐인 티켓 디스패처."}],["meta",{"property":"og:image","content":"https://dira.proofer.tech/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"docs/ref-cli.md","filePath":"docs/ref-cli.md"}'),r={name:"docs/ref-cli.md"};function a(i,t,n,s,l,p){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h1><p>두 층입니다. 워커 스크립트는 사람이 부르는 진입점이고, <code>tickets.py</code>는 대개 그 워커 스크립트가 안에서 부르는 헬퍼입니다.</p><h2 id="워커-스크립트-루트-workers-이름-sh" tabindex="-1">워커 스크립트 (<code>&lt;루트&gt;/workers/&lt;이름&gt;.sh</code>) <a class="header-anchor" href="#워커-스크립트-루트-workers-이름-sh" aria-label="Permalink to &quot;워커 스크립트 (`&lt;루트&gt;/workers/&lt;이름&gt;.sh`)&quot;">​</a></h2><p><code>tick.sh</code>를 직접 실행하면 rc=2로 거절합니다. 워커 파일이 어디 있는지 모르면 루트도 알 수 없기 때문입니다. 아래 명령은 전부 그 워커 파일을 거쳐서 씁니다.</p><table tabindex="0"><thead><tr><th>명령</th><th>뜻</th></tr></thead><tbody><tr><td>(인자 없음)</td><td>1회 디스패치. cron 진입점 — 워커 락 획득 → <code>reap</code> → 선정 → 실행</td></tr><tr><td><code>list</code></td><td>열린 티켓 큐 상태(대기·할당됨·deps 대기)</td></tr><tr><td><code>dryrun</code></td><td>claim·실행 없이 선정 결과와 조립된 프롬프트만 출력</td></tr><tr><td><code>reap</code></td><td>스테일 수거만 1회</td></tr><tr><td><code>unassign &lt;해시&gt;</code></td><td>할당 해제(<code>session_id</code> 비우기 + 진행중 접미사 떼기) → 큐 복귀. 세션이 아직 살아있으면 거부합니다</td></tr></tbody></table><p><code>list</code>·<code>dryrun</code>·<code>reap</code>·<code>unassign</code>은 큐 전체를 보기 때문에, 같은 루트의 어느 워커 파일로 불러도 결과가 같습니다.</p><h2 id="tickets-py-서브커맨드" tabindex="-1"><code>tickets.py</code> 서브커맨드 <a class="header-anchor" href="#tickets-py-서브커맨드" aria-label="Permalink to &quot;`tickets.py` 서브커맨드&quot;">​</a></h2><p>큐와 frontmatter를 다루는 헬퍼입니다. 대부분은 위 워커 스크립트가 안에서 부르고, 사람이 직접 쓰는 것은 <code>handclaim</code>과 <code>find</code> 정도입니다.</p><table tabindex="0"><thead><tr><th>명령</th><th>인자</th><th>뜻</th><th>누가 쓰나</th></tr></thead><tbody><tr><td><code>handclaim</code></td><td><code>&lt;티켓경로&gt; [&quot;&lt;owner&gt;&quot;]</code></td><td>대화형 세션이 손으로 티켓을 잡습니다. <code>claim</code> + <code>pid</code>·<code>claimed_at</code>·<code>transcript</code> 기록(생존 확인용)</td><td><strong>사람</strong>(대화형 세션)</td></tr><tr><td><code>find</code></td><td><code>&lt;루트&gt; &lt;해시&gt;</code></td><td>해시로 티켓 경로를 찾습니다</td><td>사람(<code>deps</code> 적기 전 존재 확인 등) 또는 엔진</td></tr><tr><td><code>select</code></td><td><code>&lt;루트&gt;</code></td><td>미할당 열린 티켓을 생성일 오름차순으로 <code>path|hash|kind|persona</code> 줄로 냅니다</td><td>엔진(<code>tick.sh</code>가 후보를 고를 때)</td></tr><tr><td><code>list</code></td><td><code>&lt;루트&gt;</code></td><td>열린 티켓 전체 상태 표</td><td>엔진(워커 <code>list</code>가 그대로 위임)</td></tr><tr><td><code>claim</code></td><td><code>&lt;경로&gt;</code></td><td><code>&lt;hash&gt;.md</code> → <code>&lt;hash&gt;&lt;진행중접미사&gt;.md</code> 원자적 잡기</td><td>엔진</td></tr><tr><td><code>release</code></td><td><code>&lt;경로&gt;</code></td><td>진행중 → 원래 이름으로 되돌리기(백로그 복귀)</td><td>엔진</td></tr><tr><td><code>assign</code></td><td><code>&lt;경로&gt; &lt;sid&gt; [&quot;&lt;owner&gt;&quot;]</code></td><td>frontmatter에 <code>session_id</code>·<code>assigned_at</code>(·<code>owner</code>) 기록</td><td>엔진</td></tr><tr><td><code>setpid</code></td><td><code>&lt;경로&gt; &lt;pid&gt;</code></td><td>frontmatter에 <code>pid</code> 기록</td><td>엔진</td></tr><tr><td><code>setinbox</code></td><td><code>&lt;경로&gt; &lt;inbox경로&gt;</code></td><td>frontmatter에 <code>inbox</code>(참견 FIFO 경로) 기록</td><td>엔진</td></tr><tr><td><code>clear</code></td><td><code>&lt;경로&gt;</code></td><td><code>session_id</code>·<code>assigned_at</code>·<code>pid</code>·<code>inbox</code> 비우기</td><td>엔진(<code>unassign</code>·디스패치 실패 경로)</td></tr><tr><td><code>reap</code></td><td><code>&lt;루트&gt;</code></td><td>세션이 죽은 진행중 티켓을 백로그로 회수</td><td>엔진(매 tick 맨 앞)</td></tr></tbody></table><p><code>select</code>는 <code>find</code>처럼 스크립트를 짜 붙일 때 그대로 부를 수 있습니다. 다만 사람이 평소에 큐를 만지는 자리는 워커 스크립트의 <code>list</code>·<code>dryrun</code>·<code>unassign</code>과 <code>handclaim</code> 하나로 충분합니다.</p><p>다음은 <a href="/docs/ref-frontmatter">frontmatter 필드</a>입니다.</p>',11)])])}const m=d(r,[["render",a]]);export{g as __pageData,m as default};
